#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
int main(){int n;cin>>n;vector<int>a(n),sa(n),rank(n),tmp(n);for(auto&v:a)cin>>v;auto sorted=a;sort(sorted.begin(),sorted.end());sorted.erase(unique(sorted.begin(),sorted.end()),sorted.end());for(int i=0;i<n;i++){rank[i]=lower_bound(sorted.begin(),sorted.end(),a[i])-sorted.begin();sa[i]=i;}for(int len=1;len<n;len*=2){sort(sa.begin(),sa.end(),[&](int x,int y){if(rank[x]!=rank[y])return rank[x]<rank[y];return (x+len<n?rank[x+len]:-1)<(y+len<n?rank[y+len]:-1);});tmp[sa[0]]=0;for(int i=1;i<n;i++){int x=sa[i-1],y=sa[i];tmp[y]=tmp[x]+(rank[x]!=rank[y]||(x+len<n?rank[x+len]:-1)!=(y+len<n?rank[y+len]:-1));}rank=tmp;if(rank[sa.back()]==n-1)break;}for(int i=0;i<n;i++)rank[sa[i]]=i;vector<int>height(n);for(int i=0,k=0;i<n;i++){int p=rank[i];if(!p){k=0;continue;}int j=sa[p-1];while(i+k<n&&j+k<n&&a[i+k]==a[j+k])k++;height[p]=k;if(k)k--;}vector<int>logs(n+1);for(int i=2;i<=n;i++)logs[i]=logs[i/2]+1;vector<vector<int>>st(logs[n]+1,vector<int>(n));st[0]=height;for(int j=1;j<(int)st.size();j++)for(int i=0;i+(1<<j)<=n;i++)st[j][i]=min(st[j-1][i],st[j-1][i+(1<<(j-1))]);auto lcp=[&](int x,int y){int l=rank[x],r=rank[y];if(l>r)swap(l,r);l++;int k=logs[r-l+1];return min(st[k][l],st[k][r-(1<<k)+1]);};map<int,vector<int>>positions;for(int i=0;i<n;i++)positions[a[i]].push_back(i);vector<pair<int,int>>candidates;for(auto&[v,p]:positions)for(int i=0;i<(int)p.size();i++)for(int j=i+1;j<(int)p.size();j++){int len=p[j]-p[i];if(p[i]+2*len<=n&&lcp(p[i],p[j])>=len)candidates.push_back({len,p[i]});}sort(candidates.begin(),candidates.end());int start=0;for(auto[len,p]:candidates)if(p>=start)start=p+len;cout<<n-start<<'\n';for(int i=start;i<n;i++)cout<<a[i]<<' ';cout<<'\n';}
